    devices_intro: "PaperGames работает в веб-браузере электронного ридера. На каких ридерах он действительно работает, известно только там, где кто-то попробовал и сообщил об этом. На этой странице перечислены эти устройства, и так же ясно сказано, что не проверялось.",
