    history_title: "Библиотека истории игр",
    history_intro: "У каждой игры в этой коллекции своя история – некоторым более пяти тысяч лет, другим едва ли исполнилось десятилетие. Читайте их здесь, примерно в порядке появления, или переходите сразу к полной истории любой игры.",
    history_dates_note: "Даты для самых древних игр приблизительны – их точное происхождение часто теряется в истории или оспаривается историками.",
    history_read_more: "Полная история →",
    home_history_title: "Интересно, откуда взялись эти игры?",
    home_history_desc: "Прочитайте историю происхождения каждой игры, от Древнего Египта до последнего десятилетия – никакого просмотра каталога, только история.",
    home_chess_desc: "Классическая игра. Локально вдвоём, против встроенного движка или онлайн через Lichess.",
    home_go_desc: "Древняя территориальная игра. Локально вдвоём или против встроенного движка, три размера доски, три уровня сложности.",
    home_checkers_desc: "Классическая игра на прыжки и взятия. Локально вдвоём или против встроенного движка, три уровня сложности.",
    home_ur_desc: "Игра на удачу возрастом 4600 лет, заново открытая в древней Месопотамии. Локально вдвоём или против встроенного движка, с полями-розетками и взятием попаданием на поле соперника.",
    home_morris_desc: "Многовековая стратегическая игра: расставляйте и передвигайте фишки, чтобы составить мельницы. Локально вдвоём или против встроенного движка, с классическим правилом полёта в эндшпиле.",
    home_backgammon_desc: "Классическая игра в кости на удачу. Локально вдвоём или против встроенного движка, с баром, выводом шашек и снятием одиночных шашек.",
    home_xiangqi_desc: "Китайские шахматы: полководцы, слоны, пушки и другие фигуры на сетке 9x10. Локально вдвоём или против встроенного движка, с переключением между классическими иероглифами и символами западного стиля.",
    home_mancala_desc: "Одна из старейших игровых семей в мире: сейте семена по доске, чтобы заполнить свою казну. Локально вдвоём или против встроенного движка, со взятиями и дополнительными ходами.",
    home_reversi_desc: "Меняйте цвет доски, окружая фишки соперника. Локально вдвоём или против встроенного движка.",
