    twenty48_right: "Вправо",
    mahjong_new_game: "Новая игра",
    mahjong_shuffle: "Перемешать оставшиеся кости",
    chess_history_intro: "От древнеиндийской военной игры до самой изученной настольной игры в мире — шахматы пересекли континенты и века, чтобы стать тем, чем они являются сегодня.",
    go_history_intro: "Го — одна из старейших настольных игр, до сих пор играемых в первоначальном виде: игра о территории и камнях, чьи корни, вероятно, уходят более чем на 2500 лет назад в Китай.",
    checkers_history_intro: "Шашки (дамка) — игра простых правил и глубокой стратегии, рождённая из сочетания древней доски с более новым способом взятия фигур.",
    ur_history_intro: "Возрастом примерно в 4600 лет, «Царская игра Ура» — одна из старейших настольных игр из когда-либо найденных, и благодаря детективной работе, растянувшейся на два тысячелетия, одна из немногих древних игр, в которую мы всё ещё можем сыграть по её первоначальным правилам.",
    morris_history_intro: "Мало какая игра была вырезана на стольких разных поверхностях за столько веков, как мельница — от крыш египетских храмов до клуатров английских соборов.",
    backgammon_history_intro: "Родословная нард проходит почти через каждую цивилизацию, когда-либо бросавшую кости — от древней Месопотамии и Рима до кофеен современного Ближнего Востока.",
    xiangqi_history_intro: "Китайские шахматы разделяют глубокие корни с международными шахматами, но за более чем тысячу лет прошли свой собственный путь, чтобы стать игрой, в которую сегодня играют сотни миллионов человек.",
    mancala_history_intro: "Манкала — это не одна игра, а целое семейство игр, одно из старейших игровых семейств на Земле, построенное вокруг простого универсального действия — перекладывания семян или камешков между лунками.",
    reversi_history_intro: "Викторианская салонная игра, дважды переизобретённая с разницей более чем в столетие.",
    fourinarow_history_intro: "Простая идея на основе силы тяжести, превратившаяся в одну из самых продаваемых игр XX века.",
    gomoku_history_intro: "Простая игра на выстраивание в ряд, чья простота вынудила соревнующихся игроков изменить её правила.",
    tictactoe_history_intro: "Пожалуй, самая известная игра на бумаге – с корнями в Древнем Риме и местом в истории компьютеров.",
    senet_history_intro: "Одна из старейших настольных игр из когда-либо найденных — и одна из тех, чьи точные правила были утрачены на тысячи лет.",
    shogi_history_intro: "Японский вариант шахматного семейства и единственная крупная его разновидность, где взятая фигура не покидает игру — она переходит на сторону того, кто её взял.",
    sudoku_history_intro: "В отличие от любой другой игры в этой коллекции, у судоку вообще нет древней родословной — оно едва старше персонального компьютера.",
    pegsolitaire_history_intro: "Головоломка для одного игрока, достаточно старая, чтобы обзавестись собственной придворной легендой, и предмет одного из самых удивительных результатов в занимательной математике.",
    minesweeper_history_intro: "Головоломка, чьё определяющее правило — полностью безопасный первый ход — стало стандартом лишь тогда, когда компьютеры, а не печатная страница, смогли генерировать свежую доску по требованию.",
    nonogram_history_intro: "Логическая головоломка, изобретённая независимо, на противоположных концах света, в течение нескольких лет друг от друга — и названная в честь одного из своих двух изобретателей.",
    twenty48_history_intro: "Игра, почти целиком собранная из чужих идей, сделанная за один выходной и склонированная бо́льшим числом людей, чем, пожалуй, любая браузерная игра до неё.",
    mahjong_history_intro: "Одиночная игра на составление пар из костей, названная в честь совершенно другой игры для четырёх игроков и визуально заимствующая у неё почти всё, кроме собственно правил.",
    back_home: "← Назад на главную",
