    seo_desc_index: "{games} классических настольных игр для e-ink ридеров и планшетов. Шахматы, го, нарды, судоку и другое. Бесплатно, офлайн, без рекламы, на 12 языках.",
    seo_title_about: "О PaperGames – {games} бесплатных настольных игр для e-ink",
    seo_desc_about: "Зачем существует PaperGames, как он устроен и как поддержать проект. Бесплатная офлайн-коллекция из {games} классических настольных игр и головоломок без рекламы.",
    nav_calm: "Спокойная игра",
    about_calm_link: "Спокойная игра: без анимаций, без звуков, без рекламы",
    calm_intro: "PaperGames создан для спокойной игры. Конкретно это значит:",
    calm_point_1: "Без анимаций: ничего не мигает, не скользит и не прыгает. Каждое изменение появляется сразу.",
    calm_point_2: "Без звуков.",
    calm_point_3: "Без рекламы и уведомлений. Учётная запись не нужна – только онлайн-шахматы работают через учётную запись Lichess.",
    calm_point_4: "Без слежки и без cookie. Сохранённые игры и статистика остаются в браузере на вашем устройстве.",
    calm_point_5: "Сделано для ридеров с e-ink: тёмный текст на светлом фоне, а различия никогда не обозначены только серым или цветом.",
    calm_point_6: "Без спешки. Исключения: «Слова по категориям» с необязательным временем раунда (по умолчанию выключено), часы в «Сапёре» и время на обдумывание в онлайн-шахматах на Lichess.",
