    msg_pairs_vehicle_submarine: "Подводная лодка",
    pairs_history_intro: "Игра, которой вовсе не нужна книжка с правилами: откройте две карты и запомните, где что лежало.",
    msg_pairs_no_pair: "Не пара. Коснитесь любого места, чтобы перевернуть обе карты обратно.",
    msg_pairs_turn_card: "Откройте карту.",
