    msg_cn_r_mixed: "Выбери карты одного достоинства (и дикие карты).",
    msg_cn_r_wildmeld: "Только дикие карты: коснись одной из своих комбинаций, чтобы добавить их.",
    msg_cn_r_black: "Чёрные тройки можно выложить только при выходе.",
    msg_cn_r_keep: "Выйти пока нельзя (нужны две канасты): оставь хотя бы одну карту для сброса.",
    msg_cn_last_card: "Добавь последнюю карту к комбинации, чтобы выйти.",
    game_bridge: "Bridge",
    home_bridge_desc: "Контрактный бридж вчетвером: ты и твой партнёр-компьютер против двух компьютеров. Торговля с кнопками, болван открыт на столе, подсчёт по системе «Чикаго» (четыре сдачи) или роббер.",
    br_history_intro: "Бридж происходит от виста; первые известные правила («Biritch, or Russian Whist») относятся к 1886 году, контрактный бридж — к 1925.",
    quickrules_bridge_1: "Назначь, сколько взяток сверх шести возьмёт твоя сторона, с козырной мастью или без козыря; самая высокая заявка становится контрактом.",
    quickrules_bridge_2: "Разыгрывающий играет обеими руками: болван (его партнёр) лежит открыто. Ходи в масть; старший козырь выигрывает.",
    quickrules_bridge_3: "Выполни контракт, чтобы получить очки; если взяток не хватит, очки получат соперники. «Чикаго»: четыре сдачи.",
