    game_tenpairs: "Пары до десяти",
    home_tenpairs_desc: "Головоломка на бумаге: вычёркиваешь пары цифр, равные или дающие вместе 10, если они «видят» друг друга. Ходов нет — дописываешь оставшиеся цифры. Классический или случайный старт, три уровня.",
    tp_history_intro: "Головоломка из школьных тетрадей; её происхождение не задокументировано.",
    quickrules_tenpairs_1: "Коснись двух цифр, которые равны (3 и 3) или вместе дают 10 (3 и 7), чтобы вычеркнуть их.",
    quickrules_tenpairs_2: "Они должны видеть друг друга: стоять рядом по горизонтали, вертикали или диагонали либо только с вычеркнутыми клетками между ними; по горизонтали — и через конец строки.",
    quickrules_tenpairs_3: "Ходов нет? Нажми «Дописать»: оставшиеся цифры записываются ещё раз в конце (не больше 5 раз). Вычеркни все цифры, чтобы победить.",
