    game_mathcross: "Сетка вычислений",
    home_mathcross_desc: "Расставьте числа от 1 до 9, каждое один раз, чтобы каждая строка и каждый столбец сходились - считаем слева направо. Три уровня, всегда ровно одно решение, без угадывания.",
    mc_history_intro: "Числовая головоломка из вычислений в строках и столбцах, родственная древнему магическому квадрату из чисел от 1 до 9.",
    quickrules_mathcross_1: "Впишите числа от 1 до 9 в клетки, каждое ровно один раз.",
    quickrules_mathcross_2: "Каждая строка и каждый столбец должны давать свой результат. Считаем слева направо (сверху вниз), без приоритета умножения: 3 + 4 × 2 = 14.",
    quickrules_mathcross_3: "Коснитесь клетки, а затем числа. Галочка или крестик показывает, сходится ли заполненная строка или столбец.",
    game_cardduel: "Карточная дуэль",
    home_cardduel_desc: "Фэнтезийная карточная игра для двух магов: существа и заклинания, четыре готовые колоды леса, огня, воды и камня. Против компьютера на трёх уровнях или вдвоём на одном устройстве.",
    quickrules_cardduel_1: "Снизь жизнь вражеского мага с 20 до 0.",
    quickrules_cardduel_2: "Каждый ход у тебя на 1 силу больше (до 10). Коснись карты, затем «Сыграть»: существа остаются на столе, заклинания действуют один раз.",
    quickrules_cardduel_3: "Чтобы атаковать, коснись готового существа (толстая рамка), затем цели. Сначала нужно атаковать Заслон.",
