    home_villains_desc: "Каждый играет злодеем из сказок братьев Гримм со своей целью – ведьмой, волком, Румпельштильцхеном и другими, – а остальные ставят ему на пути героев. От 2 до 4 игроков, против компьютера или на одном устройстве.",
