    ab_item_goldenseed: "Золотое семечко",
    ab_room_cave_1: "С потолка в маленькую чистую лужицу капает вода.",
    ab_room_cave_2: "Из стен растут синие кристаллы и мягко светятся.",
    ab_room_cave_3: "Узкий проход. Приходится пригнуться под низкой скалой.",
    ab_room_cave_4: "Старые вагонетки стоят на ржавых рельсах. Когда-то здесь кто-то работал.",
    ab_room_cave_5: "Пещера выходит в высокий зал. Твои шаги отдаются эхом.",
    ab_room_cave_6: "Пол покрыт блестящим песком. Он хрустит под сапогами.",
    ab_room_cave_7: "Из трещины в скале дует холодный ветер.",
    ab_room_cave_8: "Здесь растут грибы размером со стул. Они пахнут землёй.",
    ab_room_cave_9: "Подземный ручей шумит в каменном жёлобе.",
    ab_room_cave_10: "Одну стену покрывают странные рисунки звёзд.",
    ab_room_cave_11: "Сталактиты свисают с потолка, как каменные сосульки.",
    ab_room_cave_12: "Маленькая боковая пещера. Кто-то оставил здесь старое одеяло.",
    ab_room_cave_13: "Тропа поднимается по гладким камням, скользким от мха.",
    ab_room_cave_14: "В тёмном углу спят летучие мыши. Ты идёшь на цыпочках.",
    ab_room_cave_15: "Круглая комната с гладким, будто отполированным полом.",
    ab_room_cave_16: "Зелёный мох освещает стены бледным сиянием.",
    ab_room_cave_17: "Когда-то здесь был верёвочный мост. Остались только столбики.",
    ab_room_cave_18: "Здесь тёплый воздух. Где-то глубоко внизу что-то рокочет.",
    ab_room_cave_19: "Повсюду лежат осколки кристаллов, будто лопнул большой камень.",
    ab_room_cave_20: "Тихий уголок. Твоя лампа отбрасывает длинные тени.",
    ab_room_tower_1: "Полки, полные пыльных книг, доходят до потолка.",
    ab_room_tower_2: "Винтовая лестница вьётся вверх. Ступени скрипят.",
    ab_room_tower_3: "Вороны сидят на балке и смотрят на тебя блестящими глазами.",
    ab_room_tower_4: "Старая кухня. Над холодным очагом висит котёл.",
    ab_room_tower_5: "Через круглое окно видно лес далеко внизу.",
    ab_room_tower_6: "Кабинет с огромным столом. Чернила в чернильницах высохли.",
    ab_room_tower_7: "За стеклянной стеной медленно вращаются шестерни. Тик-так.",
    ab_room_tower_8: "Длинный коридор с портретами. Их глаза будто следят за тобой.",
    ab_room_tower_9: "Комната, полная карт. Одна из них показывает такую же башню.",
    ab_room_tower_10: "На столе горят свечи, хотя здесь, похоже, никого нет.",
    ab_room_tower_11: "Кладовая с банками сушёных трав и цветных порошков.",
    ab_room_tower_12: "Ветер свистит сквозь сломанный ставень.",
    ab_room_tower_13: "Музыкальная комната. Арфа сама по себе играет ноту.",
    ab_room_tower_14: "Узкий мостик из досок ведёт от одной стены к другой.",
    ab_room_tower_15: "Спальня с кроватью под балдахином. Занавеси все в дырах.",
    ab_room_tower_16: "Мастерская с подзорной трубой, направленной в небо.",
    ab_room_tower_17: "Чёрные перья лежат по всему полу.",
    ab_room_tower_18: "На стене висит зеркало, но в нём видна другая комната.",
    ab_room_tower_19: "Маленький балкон. Здесь наверху ветер пахнет дождём.",
    ab_room_tower_20: "Прохладный зал с полом из чёрных и белых плиток.",
    ab_room_forest_1: "Между деревьями висит туман. Едва видно собственную руку.",
    ab_room_forest_2: "Поляна, полная цветов. Пчёлы жужжат на солнце.",
    ab_room_forest_3: "Старая тропа, заросшая папоротником.",
    ab_room_forest_4: "Дуплистое дерево, такое большое, что в нём можно стоять.",
    ab_room_forest_5: "Маленький пруд. Лягушки прыгают в воду, когда ты подходишь.",
    ab_room_forest_6: "Корни толщиной с руку пересекают тропу.",
    ab_room_forest_7: "Высоко в кронах деревьев поют птицы.",
    ab_room_forest_8: "В траве лежит круг из белых камней.",
    ab_room_forest_9: "Вдоль каменной стены растут ежевичные кусты.",
    ab_room_forest_10: "Земля мягкая и зелёная от мха. Очень тихо.",
    ab_room_forest_11: "Поваленный ствол лежит над оврагом, как мост.",
    ab_room_forest_12: "Заброшенная хижина. Дверь открыта.",
    ab_room_forest_13: "Высокие сосны скрипят на ветру.",
    ab_room_forest_14: "Маленькие огоньки танцуют над болотом.",
    ab_room_forest_15: "Огромный дуб с вырезанным в коре лицом.",
    ab_room_forest_16: "Грибы растут ровным кругом.",
    ab_room_forest_17: "Ручей журчит по гладким камешкам.",
    ab_room_forest_18: "Тёмная чаща. Ветки царапают рукава.",
    ab_room_forest_19: "Солнечный холм. Отсюда туман внизу похож на море.",
    ab_room_forest_20: "Старые каменные ступени ведут между двумя берёзами.",
