    game_differences: "Найди отличия",
    home_differences_desc: "Две картинки, которые отличаются в 3, 5 или 7 местах: чего-то не хватает, другой узор, отражено или сдвинуто. Коснитесь отличия на любой из двух картинок. Без спешки, с подсказкой, если застряли. Или «Найди на картинке»: найдите от 5 до 10 предметов на большой картинке комнаты - кухни, чердака, сада и ещё девяти.",
    df_history_intro: "Головоломка, известная по газетам, детским журналам и сборникам головоломок; когда и где она появилась впервые, достоверно не задокументировано.",
    quickrules_differences_1: "Две картинки отличаются в нескольких местах - в 3, 5 или 7, в зависимости от уровня.",
    quickrules_differences_2: "Коснитесь отличия на любой картинке: оно будет обведено на обеих. Чего-то может не хватать, может быть другой узор, отражение или сдвиг.",
    quickrules_differences_3: "Ограничения по времени нет, и за неверное касание ничего не будет. Застряли? Кнопка «Подсказка» обводит область с отличием.",
