    msg_df_search_hint: "Подсказка: один из предметов в отмеченном месте.",
    game_pentomino: "Пентамино",
    home_pentomino_desc: "Сложите двенадцать фигур из пяти квадратов в прямоугольник - поворачивайте и отражайте касанием, без перетаскивания. Свободная укладка в четырёх размерах или с заданными стартовыми фигурами и ровно одним решением.",
    pt_history_intro: "Двенадцать фигур из пяти квадратов каждая: головоломку опубликовал Генри Дьюдени в 1907 году, а название «пентамино» дал Соломон Голомб в 1953 году.",
    quickrules_pentomino_1: "Заполните прямоугольник фигурами; каждая клетка будет покрыта ровно один раз.",
    quickrules_pentomino_2: "Выберите фигуру под полем, поверните или отразите её, а затем коснитесь клетки, куда должна лечь её точка. Коснитесь выложенной фигуры, чтобы снова её взять.",
    quickrules_pentomino_3: "В режиме «Заданные стартовые фигуры» некоторые фигуры лежат неподвижно, а остальные подходят только одним способом.",
