    msg_t_pt_hint_place: "Подсказка: фигура {s} ложится в отмеченное место.",
    msg_t_pt_hint_remove: "Подсказка: фигура {s} мешает решению - уберите её.",
    msg_pt_hint_none: "Подсказка: пути не найдено - уберите какую-нибудь фигуру.",
    msg_t_pt_info: "Выложено: {n} из {m} фигур",
    game_arrows: "Стрелки",
    home_arrows_desc: "Коснитесь стрелки, и она выскользнет с поля - если ей не мешает другая стрелка. Очистите всё поле; у каждой головоломки есть решение, есть отмена, подсказки и никакого ограничения времени. На уровнях «Сложный» и «Мастер» заблокированные стрелки скользят вперёд и могут застрять.",
    aw_history_intro: "Детали, которые могут скользить только в одну сторону, - родственники передвижных головоломок, ставших повальным увлечением в 1880 году; вариант со стрелками - молодая головоломка.",
    quickrules_arrows_1: "Коснитесь стрелки: она покидает поле в своём направлении, если путь до края свободен.",
    quickrules_arrows_2: "Если на пути другая стрелка, ничего не происходит - сначала уберите её. На уровнях «Сложный» и «Мастер» она вместо этого скользит до той стрелки.",
    quickrules_arrows_3: "Очистите всё поле. У каждой головоломки есть решение; «Подсказка» отмечает стрелку, которая может выйти.",
    aw_win_title: "Поле очищено!",
    aw_aria_cell: "Строка {R}, столбец {C}",
    aw_aria_empty: "пусто",
    aw_aria_arrow: "стрелка {D}",
    aw_dir_0: "вверх",
    aw_dir_1: "вправо",
    aw_dir_2: "вниз",
    aw_dir_3: "влево",
    msg_aw_start: "Коснитесь стрелки, чтобы отправить её с поля.",
    tg_level_outline: "Только контур",
    game_loosen: "Расцепи кольца",
    home_loosen_desc: "Сцепленные друг с другом кольца, каждое с разрывом: вращай их - сцепленные кольца вращаются в обратную сторону - пока они не освободятся одно за другим. Три уровня, с наименьшим числом ходов, отменой и подсказками.",
    lr_history_intro: "Головоломки с кольцами древние - китайские кольца описывали ещё около 1500 года; эта плоская версия с разрывами новая.",
    quickrules_loosen_1: "Нажми на кольцо: оно поворачивается на четверть оборота по часовой стрелке, а сцепленные с ним - в обратную сторону.",
    quickrules_loosen_2: "Кольцо свободно, когда его разрыв там, где сцепленное кольцо лежит сверху - нажми на него, и оно выйдет.",
    quickrules_loosen_3: "Убери все кольца; сначала те, что на концах. «Подсказка» показывает ход.",
    lr_win_title: "Все свободны!",
    lr_aria_ring: "Кольцо {N}, разрыв {D}",
    lr_dir_0: "вверху справа",
    lr_dir_1: "внизу справа",
    lr_dir_2: "внизу слева",
    lr_dir_3: "вверху слева",
