    lr_turn_right: "Вправо ↻",
    msg_lr_start: "Нажми на кольцо, чтобы повернуть его на четверть оборота по часовой стрелке; свободное кольцо выходит.",
    msg_t_lr_out: "Кольцо {n} свободно и выходит.",
    msg_t_lr_turned: "Кольцо {n} повёрнуто; сцепленные с ним кольца повернулись в обратную сторону.",
    msg_lr_pick: "Сначала нажми на кольцо.",
