    msg_t_lr_won: "Все кольца свободны - решено за {n} ходов!",
    msg_t_lr_info: "Осталось колец: {n} · Ходов: {m} · Минимум: {k}",
    family_rings: "Головоломки с кольцами",
    aw_level_master: "Мастер",
