    msg_aw_glided: "Стрелка скользит вперёд до следующей стрелки.",
    msg_aw_heart: "Это стоило одно сердце.",
    msg_aw_stuck: "Ни одна стрелка больше не может двигаться - отмени несколько ходов.",
    msg_aw_lost: "Сердец не осталось - попробуй эту головоломку ещё раз или начни новую.",
    msg_aw_noway: "Отсюда нет выхода - отмени несколько ходов.",
    msg_aw_hint_glide: "Подсказка: дай отмеченной стрелке скользнуть вперёд.",
    msg_t_aw_info_hearts: "Осталось стрелок: {n} · Ходов: {m} · Сердец: {k}",
    game_catplaces: "Места для котов",
    home_catplaces_desc: "В каждой строке, каждом столбце и каждой комнате должен быть ровно один кот - и два кота не могут касаться, даже углом. Логические головоломки трёх размеров, у каждой одно решение, решаются без угадывания.",
    kz_history_intro: "Правила взяты из логической головоломки, придуманной в 2003 году для чемпионата мира по головоломкам в Нидерландах; здесь место звёзд занимают спящие коты.",
    quickrules_catplaces_1: "Поставь кота в каждую строку, каждый столбец и каждую комнату (области внутри толстых линий).",
    quickrules_catplaces_2: "Два кота никогда не касаются - ни рядом, ни углом.",
    quickrules_catplaces_3: "Нажми на клетку один раз - кот, второй раз - точка (здесь кота нет), третий раз - очистить. «Подсказка» показывает клетку.",
    kz_win_title: "Решено!",
    kz_aria_cell: "Строка {R}, столбец {C}, комната {K}",
    kz_aria_empty: "пусто",
    kz_aria_cat: "кот",
    kz_aria_dot: "точка",
    msg_kz_start: "Нажми на клетку: один раз - кот, второй раз - точка, третий раз - очистить.",
    msg_kz_conflict: "Два кота в одной строке, столбце или комнате или касаются - смотри пунктирные рамки.",
    msg_kz_hint_place: "Подсказка: в отмеченной клетке должен быть кот.",
    msg_kz_hint_wrong: "Подсказка: отмеченный кот стоит не на своём месте.",
    msg_t_kz_won: "Все коты ({n}) на своих местах - решено!",
    msg_t_kz_info: "Коты: {n} из {m}",
    msg_aw_leaves: "Стрелка покидает поле.",
    msg_aw_blocked: "Заблокировано - на пути другая стрелка.",
    msg_aw_undone: "Отменено: стрелка вернулась.",
    msg_aw_hint: "Подсказка: отмеченная стрелка может выйти.",
    msg_t_aw_won: "Все стрелки вышли - решено за {n} ходов!",
    msg_t_aw_info: "Осталось стрелок: {n} · Ходы: {m} · Меньше всего: {k}",
    game_rings: "Поверни кольца",
    home_rings_desc: "От трёх до пяти колец одно в другом, на них фигуры. Поворачивайте кольца, пока каждый луч от центра не покажет одинаковую фигуру; на сложном уровне кольцо поворачивает и соседа. С наименьшим числом ходов и кнопкой подсказки.",
    rg_history_intro: "Кольца со знаками, которые поворачивают друг относительно друга, стары: Леон Баттиста Альберти в 1467 году описал шифровальный диск из двух вращающихся колец. Головоломка здесь сделана для PaperGames.",
    quickrules_rings_1: "Поворачивайте кольцо влево ↺ или вправо ↻ кнопками под рисунком.",
    quickrules_rings_2: "Цель: каждый из 8 лучей от центра показывает одинаковую фигуру на всех кольцах.",
    quickrules_rings_3: "На сложном уровне кольцо поворачивает и следующее кольцо наружу. «Подсказка» показывает хороший ход; наименьшее число ходов указано.",
