    game_matches: "Головоломки со спичками",
    home_matches_desc: "Переложите одну или две спички, чтобы неверный пример стал верным или чтобы фигура показала нужное число квадратов. 90 задач на трёх уровнях, каждая проверена компьютером; коснитесь спички, а потом свободного места - без перетаскивания.",
    mt_history_intro: "Спички стали привычной вещью в XIX веке и вскоре материалом для головоломок: в книге Professor Hoffmann «Puzzles Old and New» (1893) уже есть глава головоломок со спичками.",
