    game_tangram: "Танграм",
    home_tangram_desc: "Заполни контур семью классическими частями: треугольниками, квадратом и параллелограммом. 90 контуров на четырёх уровнях, у каждого решение проверено компьютером. В режиме «Только контур» видна лишь внешняя линия, а часть остаётся там, где ты нажмёшь, - нужно пробовать. Нажми на часть, поверни её, нажми на место - без перетаскивания.",
    tg_history_intro: "Семь деталей, вырезанных из квадрата: головоломка родом из Китая, где в 1813 году напечатали самую старую сохранившуюся книгу о ней; с 1817 года она стала повальным увлечением в Европе.",
    quickrules_tangram_1: "Выберите деталь под контуром, поверните её кнопкой «Повернуть на 45°» или отразите, а затем коснитесь места, куда она должна лечь.",
